package com.drivique.api.service;
import com.drivique.api.exception.*; import com.drivique.api.model.*; import com.drivique.api.repository.*; import java.time.*; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class PaymentReceiptService {private final PaymentReceiptRepository receipts;private final PaymentRepository payments;private final UserRepository users;private final PaymentReceiptPdfService pdfs;private final FileStorageService storage;public PaymentReceiptService(PaymentReceiptRepository receipts,PaymentRepository payments,UserRepository users,PaymentReceiptPdfService pdfs,FileStorageService storage){this.receipts=receipts;this.payments=payments;this.users=users;this.pdfs=pdfs;this.storage=storage;} @Transactional public PaymentReceipt generateFor(Payment payment){if(!"APPROVED".equalsIgnoreCase(payment.getStatus().getCode()))throw new ConflictException("Solo se generan comprobantes para pagos aprobados.");return receipts.findByPaymentId(payment.getId()).orElseGet(()->{String number=nextNumber();String url=storage.storePdf(pdfs.generate(payment,number),"payments/receipts");return receipts.saveAndFlush(new PaymentReceipt(payment,number,url));});} @Transactional public byte[] download(UUID paymentId,String email){Payment payment=payments.findById(paymentId).orElseThrow(()->new ResourceNotFoundException("Pago no encontrado"));User user=users.findByEmailIgnoreCaseAndDeletedAtIsNull(email).orElseThrow(()->new ResourceNotFoundException("Usuario no encontrado"));boolean owner=payment.getContract().getCustomer().getId().equals(user.getId());boolean staff=user.getRoles().stream().anyMatch(role->Set.of("EMPLOYEE","BRANCH_ADMIN","ADMIN","SUPER_ADMIN").contains(role.getCode()));if(!owner&&!staff)throw new ResourceNotFoundException("Pago no encontrado");PaymentReceipt receipt=generateFor(payment);return pdfs.generate(payment,receipt.getReceiptNumber());} private String nextNumber(){Instant now=Instant.now();Instant start=now.atZone(ZoneOffset.UTC).withDayOfYear(1).toLocalDate().atStartOfDay().toInstant(ZoneOffset.UTC);return "RCP-"+now.atZone(ZoneOffset.UTC).getYear()+"-"+String.format("%06d",receipts.countByCreatedAtBetween(start,now)+1);} }
